function squeezeRuns(chars: string[]): string[] {
  const out: string[] = [];
  let i = 0;
  while (i < chars.length) {
    let j = i;
    while (j < chars.length && chars[j] === chars[i]) j++;
    out.push(chars[i]);
    if (j - i > 1) out.push(...String(j - i));
    i = j;
  }
  return out;
}

