function squeezeRuns(chars: string[]): string[] {
  let read = 0, write = 0;
  while (read < chars.length) {
    const c = chars[read], start = read;
    while (read < chars.length && chars[read] === c) read++;
    chars[write++] = c;
    if (read - start > 1) {
      for (const d of String(read - start)) chars[write++] = d;
    }
  }
  chars.length = write;
  return chars;
}

